/**
 * The locale chooser.
 *
 * A static export has no server at request time, so redirect() cannot run here.
 * Cloudflare Pages sends / to /en/ at the edge; this page is the fallback.
 */
export default function Page() {
  // Not a redirect(): the reader picks a language.
  return null;
}
